// ***************
// Filename: video_pipeline_regs.sv
// Author: FPGA Cores 4 U
// Description: Register map of video_pipeline: its AXI4-Lite register slave
//   (axi4_lite_slave front end) with every register of the block, the ID
//   block first; the registers go to video_pipeline's logic on named ports,
//   its status comes back on input ports. Camera to display pipeline
//   registers: control, ISP stages, statistics, display timing, MIPI / LVDS
//   outputs, counters. Generated by ip/scripts/regmap_gen.py from
//   video_pipeline_regs.json: edit the JSON and regenerate (the IP_VERSION /
//   IP_DATE stamps are kept).
//   Register map (ADDR_W = 14, byte offsets):
//     0x000 ID          RO   "VPIP" IP identifier, 4 ASCII characters (first
//                       in [31:24])
//     0x004 VERSION     RO   version, ASCII "d.dd" (+0.01 at every source
//                       update)
//     0x008 DATE        RO   date of the last source update, BCD mm/dd/yyyy
//                       (0xMMDDYYYY)
//     0x00C reserved    RO   0
//     0x014 CTRL        RW   [0] output enable [1] HDMI (0 = DVI) [2] TPG [3]
//                       genlock [5:4] CFA [6] CSC BT.709 [7] insert point,
//                       reset 0x0
//     0x018 BYPASS      RW   stage bypass: [0] BLC [1] WB [2] DPC [3]
//                       demosaic [4] CCM [5] gamma [6] CSC [7] scaler, reset
//                       0xC0
//     0x01C STATUS      RO   [0] output locked to the camera
//     0x020 CSI         RW   [5:0] data type (RAW10) [7:6] virtual channel,
//                       reset 0x2B
//     0x024 FRAME_SIZE  RW   [15:0] camera width [31:16] height, reset 0x0
//     0x028 BLC_R       RW   black level R, reset 0x0
//     0x02C BLC_GR      RW   black level Gr, reset 0x0
//     0x030 BLC_GB      RW   black level Gb, reset 0x0
//     0x034 BLC_B       RW   black level B, reset 0x0
//     0x038 WB_R        RW   white balance gain R, Q4.8, reset 0x100
//     0x03C WB_G        RW   white balance gain G, Q4.8, reset 0x100
//     0x040 WB_B        RW   white balance gain B, Q4.8, reset 0x100
//     0x044 DPC_THR     RW   defect pixel threshold, reset 0x40
//     0x048 CCM_C00     RW   colour matrix coefficient, signed Q5.10, reset
//                       0x400
//     0x04C CCM_C01     RW   colour matrix coefficient, signed Q5.10, reset
//                       0x0
//     0x050 CCM_C02     RW   colour matrix coefficient, signed Q5.10, reset
//                       0x0
//     0x054 CCM_C10     RW   colour matrix coefficient, signed Q5.10, reset
//                       0x0
//     0x058 CCM_C11     RW   colour matrix coefficient, signed Q5.10, reset
//                       0x400
//     0x05C CCM_C12     RW   colour matrix coefficient, signed Q5.10, reset
//                       0x0
//     0x060 CCM_C20     RW   colour matrix coefficient, signed Q5.10, reset
//                       0x0
//     0x064 CCM_C21     RW   colour matrix coefficient, signed Q5.10, reset
//                       0x0
//     0x068 CCM_C22     RW   colour matrix coefficient, signed Q5.10, reset
//                       0x400
//     0x06C CCM_OFF_R   RW   colour matrix offset R (signed), reset 0x0
//     0x070 CCM_OFF_G   RW   colour matrix offset G (signed), reset 0x0
//     0x074 CCM_OFF_B   RW   colour matrix offset B (signed), reset 0x0
//     0x078 GAMMA_ADDR  RW   gamma table index for the next GAMMA_DATA write,
//                       reset 0x0
//     0x07C GAMMA_DATA  WO   [7:0] writes table[index], the index auto-
//                       increments
//     0x080 STAT_THR    RW   statistics clip threshold (10 bit), reset 0x3E8
//     0x084 STAT_SUM_R  RO   sum of R, last frame (low 32 bits)
//     0x088 STAT_SUM_G  RO   sum of G, last frame (low 32 bits)
//     0x08C STAT_SUM_B  RO   sum of B, last frame (low 32 bits)
//     0x090 STAT_PIX    RO   pixels, last frame
//     0x094 STAT_CLIP   RO   clipped pixels, last frame
//     0x098 STAT_FRAMES RO   frames measured
//     0x09C H_ACTIVE    RW   display: active pixels per line, reset 0x0
//     0x0A0 H_FP        RW   display: horizontal front porch, reset 0x0
//     0x0A4 H_SYNC      RW   display: horizontal sync width, reset 0x0
//     0x0A8 H_BP        RW   display: horizontal back porch, reset 0x0
//     0x0AC V_ACTIVE    RW   display: active lines, reset 0x0
//     0x0B0 V_FP        RW   display: vertical front porch, reset 0x0
//     0x0B4 V_SYNC      RW   display: vertical sync width, reset 0x0
//     0x0B8 V_BP        RW   display: vertical back porch, reset 0x0
//     0x0BC SYNC_POL    RW   [0] hsync [1] vsync active high, reset 0x0
//     0x0C0 LOCK_MAX    RW   genlock: max extra blanking lines, reset 0x3FF
//     0x0C4 START_LEVEL RW   pixels buffered before a frame starts, reset
//                       0x10
//     0x0C8 AVI         RW   HDMI AVI: [6:0] VIC [9:8] picture aspect [11:10]
//                       RGB range, reset 0x200
//     0x0CC CSI_FRAMES  RO   camera frames received
//     0x0D0 ECC_CORR    RO   CSI-2 header ECC corrections
//     0x0D4 ECC_ERR     RO   CSI-2 header ECC errors
//     0x0D8 CRC_ERR     RO   CSI-2 payload CRC errors
//     0x0DC UNDERFLOWS  RO   display underflows
//     0x0E0 DPC_CORR    RO   defective pixels corrected
//     0x0E4 CSI_OVERFLOW RO   CSI overflow events (bridge FIFO full; a burst
//                       of lost words counts once)
//     0x0E8 OUT_CTRL    RW   [0] LVDS dual [1] LVDS 18 bpp [2] JEIDA [4] DSI
//                       video [5] DSI EoTp [7:6] DSI VC [8] CSI-2 TX [9]
//                       YUV422 [11:10] VC, reset 0x0
//     0x0EC DSI_GAPS    RW   [15:0] LP clocks after a sync packet, [31:16]
//                       after pixels, reset 0x6000A
//     0x0F0 CSITX_GAP   RW   LP clocks between CSI-2 TX packets, reset 0x8
//     0x0F4 DSI_CMD     WO   queue a DSI command {[24] long, [23:16] data
//                       type, [15:0] data / word count}
//     0x0F8 DSI_CMD_BYTE WO   [7:0] next payload byte of a long command
//     0x0FC TX_STATUS   RO   [0] DSI command queue busy
//     0x100 DSI_DROPS   RO   lines DSI could not send in time (dropped, or a
//                       burst that ran dry)
//     0x104 CSITX_DROPS RO   lines CSI-2 TX could not send in time (dropped,
//                       or a burst that ran dry)
//     0x108 CSITX_FRAMES RO   frames sent by CSI-2 TX
//     0x10C BUILD_CFG   RO   interfaces built: [0] CSI-2 RX [1] HDMI [2] LVDS
//                       [3] DSI [4] CSI-2 TX [5] scaler [6] insert point
//   Access: RW read / write (byte strobes), RO read only (writes answer
//   SLVERR), W1C hardware sets / software writes 1 to clear (a set wins), W1S
//   software writes 1 to set / hardware clears, WO write only (reads 0), CMD
//   reads the hardware value, a write gives a pulse with its data. Unmapped
//   words read 0 and ignore writes; above the map: DECERR. Clock - clk. Reset
//   - synchronous active low rst_n. Latency - 2 clocks per write and read.
// Date: 2026-10-21
