  localparam logic [31:0] IP_DATE    = 32'h10122026;   // mm/dd/yyyy, BCD
  localparam logic [13:0] A_ID = 14'h0, A_VERSION = 14'h4, A_DATE = 14'h8;
  localparam logic [13:0] A_CTRL = 14'h14;
  localparam logic [13:0] A_BYPASS = 14'h18;
  localparam logic [13:0] A_STATUS = 14'h1C;
  localparam logic [13:0] A_CSI = 14'h20;
  localparam logic [13:0] A_FRAME_SIZE = 14'h24;
  localparam logic [13:0] A_BLC_R = 14'h28;
  localparam logic [13:0] A_BLC_GR = 14'h2C;
  localparam logic [13:0] A_BLC_GB = 14'h30;
  localparam logic [13:0] A_BLC_B = 14'h34;
  localparam logic [13:0] A_WB_R = 14'h38;
  localparam logic [13:0] A_WB_G = 14'h3C;
  localparam logic [13:0] A_WB_B = 14'h40;
  localparam logic [13:0] A_DPC_THR = 14'h44;
  localparam logic [13:0] A_CCM_C00 = 14'h48;
