  logic             wr_en, rd_en, wr_err_q;
  logic [13:0]       wr_addr, rd_addr, rd_addr_q;
  wire unused_addr_lsbs = &{1'b0, wr_addr[1:0], rd_addr[1:0]};   // word access: the byte offset is not decoded
  logic [31:0]      wr_data, rd_data;
  logic [3:0]       wr_strb;
  regbus_if #(.ADDR_W(14)) bus ();               // register bus of the AXI4-Lite front end
  assign wr_en = bus.wr;
  assign wr_addr = bus.waddr;
  assign wr_data = bus.wdata;
  assign wr_strb = bus.wstrb;
  assign rd_en = bus.rd;
  assign rd_addr = bus.raddr;
  assign bus.wr_err = wr_err_q;
  assign bus.rdata = rd_data;
  assign bus.rd_valid = 1'b1;
  assign bus.rd_err = 1'b0;
  axi4_lite_slave #(
    .ADDR_W(14),
    .READ_WAIT(0),
    .MAP_WORDS(MAP_WORDS)
  ) u_axil (
    .aclk(clk),
    .aresetn(rst_n),
    .s_axil(s_axil),
    .bus(bus)
  );
  wire [13:0] wa = {wr_addr[13:2], 2'b00};
  // byte strobes applied to the written word
  logic [31:0] wmask;
  always_comb for (int b = 0; b < 4; b++) wmask[b*8 +: 8] = {8{wr_strb[b]}};

  // ---------------- writes
  logic [31:0] ctrl_q;
  logic [31:0] bypass_q;
  logic [31:0] csi_q;
  logic [31:0] frame_size_q;
  logic [31:0] blc_r_q;
  logic [31:0] blc_gr_q;
  logic [31:0] blc_gb_q;
  logic [31:0] blc_b_q;
  logic [31:0] wb_r_q;
  logic [31:0] wb_g_q;
  logic [31:0] wb_b_q;
  logic [31:0] dpc_thr_q;
  logic [31:0] ccm_c00_q;
  logic [31:0] ccm_c01_q;
  logic [31:0] ccm_c02_q;
  logic [31:0] ccm_c10_q;
  logic [31:0] ccm_c11_q;
  logic [31:0] ccm_c12_q;
  logic [31:0] ccm_c20_q;
  logic [31:0] ccm_c21_q;
  logic [31:0] ccm_c22_q;
  logic [31:0] ccm_off_r_q;
  logic [31:0] ccm_off_g_q;
  logic [31:0] ccm_off_b_q;
  logic [31:0] gamma_addr_q;
  logic [31:0] gamma_data_q;
  logic [31:0] stat_thr_q;
  logic [31:0] h_active_q;
  logic [31:0] h_fp_q;
  logic [31:0] h_sync_q;
  logic [31:0] h_bp_q;
  logic [31:0] v_active_q;
  logic [31:0] v_fp_q;
