      bypass_q <= 32'hC0;
      bypass_wr_o <= 1'b0;
      csi_q <= 32'h2B;
      csi_wr_o <= 1'b0;
      frame_size_q <= 32'h0;
      frame_size_wr_o <= 1'b0;
      blc_r_q <= 32'h0;
      blc_r_wr_o <= 1'b0;
      blc_gr_q <= 32'h0;
      blc_gr_wr_o <= 1'b0;
      blc_gb_q <= 32'h0;
      blc_gb_wr_o <= 1'b0;
      blc_b_q <= 32'h0;
      blc_b_wr_o <= 1'b0;
      wb_r_q <= 32'h100;
      wb_r_wr_o <= 1'b0;
      wb_g_q <= 32'h100;
      wb_g_wr_o <= 1'b0;
      wb_b_q <= 32'h100;
      wb_b_wr_o <= 1'b0;
      dpc_thr_q <= 32'h40;
      dpc_thr_wr_o <= 1'b0;
      ccm_c00_q <= 32'h400;
      ccm_c00_wr_o <= 1'b0;
      ccm_c01_q <= 32'h0;
      ccm_c01_wr_o <= 1'b0;
      ccm_c02_q <= 32'h0;
      ccm_c02_wr_o <= 1'b0;
      ccm_c10_q <= 32'h0;
      ccm_c10_wr_o <= 1'b0;
      ccm_c11_q <= 32'h400;
      ccm_c11_wr_o <= 1'b0;
      ccm_c12_q <= 32'h0;
      ccm_c12_wr_o <= 1'b0;
      ccm_c20_q <= 32'h0;
      ccm_c20_wr_o <= 1'b0;
      ccm_c21_q <= 32'h0;
      ccm_c21_wr_o <= 1'b0;
      ccm_c22_q <= 32'h400;
      ccm_c22_wr_o <= 1'b0;
      ccm_off_r_q <= 32'h0;
      ccm_off_r_wr_o <= 1'b0;
      ccm_off_g_q <= 32'h0;
      ccm_off_g_wr_o <= 1'b0;
      ccm_off_b_q <= 32'h0;
      ccm_off_b_wr_o <= 1'b0;
      gamma_addr_q <= 32'h0;
      gamma_addr_wr_o <= 1'b0;
      gamma_data_q <= '0;
      gamma_data_wr_o <= 1'b0;
      stat_thr_q <= 32'h3E8;
      stat_thr_wr_o <= 1'b0;
      h_active_q <= 32'h0;
      h_active_wr_o <= 1'b0;
      h_fp_q <= 32'h0;
      h_fp_wr_o <= 1'b0;
      h_sync_q <= 32'h0;
      h_sync_wr_o <= 1'b0;
      h_bp_q <= 32'h0;
      h_bp_wr_o <= 1'b0;
      v_active_q <= 32'h0;
      v_active_wr_o <= 1'b0;
      v_fp_q <= 32'h0;
      v_fp_wr_o <= 1'b0;
      v_sync_q <= 32'h0;
      v_sync_wr_o <= 1'b0;
      v_bp_q <= 32'h0;
      v_bp_wr_o <= 1'b0;
      sync_pol_q <= 32'h0;
      sync_pol_wr_o <= 1'b0;
      lock_max_q <= 32'h3FF;
      lock_max_wr_o <= 1'b0;
      start_level_q <= 32'h10;
      start_level_wr_o <= 1'b0;
      avi_q <= 32'h200;
      avi_wr_o <= 1'b0;
      out_ctrl_q <= 32'h0;
      out_ctrl_wr_o <= 1'b0;
      dsi_gaps_q <= 32'h6000A;
      dsi_gaps_wr_o <= 1'b0;
      csitx_gap_q <= 32'h8;
      csitx_gap_wr_o <= 1'b0;
      dsi_cmd_q <= '0;
      dsi_cmd_wr_o <= 1'b0;
      dsi_cmd_byte_q <= '0;
      dsi_cmd_byte_wr_o <= 1'b0;
      wr_err_q <= 1'b0;
    end else begin
      wr_err_q <= wr_en && (wa == A_ID || wa == A_VERSION || wa == A_DATE || wa == A_STATUS || wa == A_STAT_SUM_R || wa == A_STAT_SUM_G || wa == A_STAT_SUM_B || wa == A_STAT_PIX || wa == A_STAT_CLIP || wa == A_STAT_FRAMES || wa == A_CSI_FRAMES || wa == A_ECC_CORR || wa == A_ECC_ERR || wa == A_CRC_ERR || wa == A_UNDERFLOWS || wa == A_DPC_CORR || wa == A_CSI_OVERFLOW || wa == A_TX_STATUS || wa == A_DSI_DROPS || wa == A_CSITX_DROPS || wa == A_CSITX_FRAMES || wa == A_BUILD_CFG);   // writes to read-only words: SLVERR
      begin
        ctrl_wr_o <= wr_en && wa == A_CTRL;
        if (wr_en && wa == A_CTRL) ctrl_q <= (ctrl_q & ~wmask) | (wr_data & wmask);
      end
      begin
        bypass_wr_o <= wr_en && wa == A_BYPASS;
        if (wr_en && wa == A_BYPASS) bypass_q <= (bypass_q & ~wmask) | (wr_data & wmask);
      end
      begin
        csi_wr_o <= wr_en && wa == A_CSI;
        if (wr_en && wa == A_CSI) csi_q <= (csi_q & ~wmask) | (wr_data & wmask);
      end
      begin
        frame_size_wr_o <= wr_en && wa == A_FRAME_SIZE;
        if (wr_en && wa == A_FRAME_SIZE) frame_size_q <= (frame_size_q & ~wmask) | (wr_data & wmask);
      end
      begin
        blc_r_wr_o <= wr_en && wa == A_BLC_R;
        if (wr_en && wa == A_BLC_R) blc_r_q <= (blc_r_q & ~wmask) | (wr_data & wmask);
      end
      begin
        blc_gr_wr_o <= wr_en && wa == A_BLC_GR;
        if (wr_en && wa == A_BLC_GR) blc_gr_q <= (blc_gr_q & ~wmask) | (wr_data & wmask);
      end
      begin
        blc_gb_wr_o <= wr_en && wa == A_BLC_GB;
        if (wr_en && wa == A_BLC_GB) blc_gb_q <= (blc_gb_q & ~wmask) | (wr_data & wmask);
      end
      begin
        blc_b_wr_o <= wr_en && wa == A_BLC_B;
        if (wr_en && wa == A_BLC_B) blc_b_q <= (blc_b_q & ~wmask) | (wr_data & wmask);
      end
      begin
        wb_r_wr_o <= wr_en && wa == A_WB_R;
        if (wr_en && wa == A_WB_R) wb_r_q <= (wb_r_q & ~wmask) | (wr_data & wmask);
      end
      begin
        wb_g_wr_o <= wr_en && wa == A_WB_G;
        if (wr_en && wa == A_WB_G) wb_g_q <= (wb_g_q & ~wmask) | (wr_data & wmask);
      end
      begin
        wb_b_wr_o <= wr_en && wa == A_WB_B;
        if (wr_en && wa == A_WB_B) wb_b_q <= (wb_b_q & ~wmask) | (wr_data & wmask);
      end
      begin
        dpc_thr_wr_o <= wr_en && wa == A_DPC_THR;
        if (wr_en && wa == A_DPC_THR) dpc_thr_q <= (dpc_thr_q & ~wmask) | (wr_data & wmask);
      end
      begin
        ccm_c00_wr_o <= wr_en && wa == A_CCM_C00;
        if (wr_en && wa == A_CCM_C00) ccm_c00_q <= (ccm_c00_q & ~wmask) | (wr_data & wmask);
      end
      begin
