        if (wr_en && wa == A_CCM_C01) ccm_c01_q <= (ccm_c01_q & ~wmask) | (wr_data & wmask);
      end
      begin
        ccm_c02_wr_o <= wr_en && wa == A_CCM_C02;
        if (wr_en && wa == A_CCM_C02) ccm_c02_q <= (ccm_c02_q & ~wmask) | (wr_data & wmask);
      end
      begin
        ccm_c10_wr_o <= wr_en && wa == A_CCM_C10;
        if (wr_en && wa == A_CCM_C10) ccm_c10_q <= (ccm_c10_q & ~wmask) | (wr_data & wmask);
      end
      begin
        ccm_c11_wr_o <= wr_en && wa == A_CCM_C11;
        if (wr_en && wa == A_CCM_C11) ccm_c11_q <= (ccm_c11_q & ~wmask) | (wr_data & wmask);
      end
      begin
        ccm_c12_wr_o <= wr_en && wa == A_CCM_C12;
        if (wr_en && wa == A_CCM_C12) ccm_c12_q <= (ccm_c12_q & ~wmask) | (wr_data & wmask);
      end
      begin
        ccm_c20_wr_o <= wr_en && wa == A_CCM_C20;
        if (wr_en && wa == A_CCM_C20) ccm_c20_q <= (ccm_c20_q & ~wmask) | (wr_data & wmask);
      end
      begin
        ccm_c21_wr_o <= wr_en && wa == A_CCM_C21;
        if (wr_en && wa == A_CCM_C21) ccm_c21_q <= (ccm_c21_q & ~wmask) | (wr_data & wmask);
      end
      begin
        ccm_c22_wr_o <= wr_en && wa == A_CCM_C22;
        if (wr_en && wa == A_CCM_C22) ccm_c22_q <= (ccm_c22_q & ~wmask) | (wr_data & wmask);
      end
      begin
        ccm_off_r_wr_o <= wr_en && wa == A_CCM_OFF_R;
        if (wr_en && wa == A_CCM_OFF_R) ccm_off_r_q <= (ccm_off_r_q & ~wmask) | (wr_data & wmask);
      end
      begin
        ccm_off_g_wr_o <= wr_en && wa == A_CCM_OFF_G;
        if (wr_en && wa == A_CCM_OFF_G) ccm_off_g_q <= (ccm_off_g_q & ~wmask) | (wr_data & wmask);
      end
      begin
        ccm_off_b_wr_o <= wr_en && wa == A_CCM_OFF_B;
        if (wr_en && wa == A_CCM_OFF_B) ccm_off_b_q <= (ccm_off_b_q & ~wmask) | (wr_data & wmask);
      end
      begin
        gamma_addr_wr_o <= wr_en && wa == A_GAMMA_ADDR;
        if (wr_en && wa == A_GAMMA_ADDR) gamma_addr_q <= (gamma_addr_q & ~wmask) | (wr_data & wmask);
      end
      begin
