        if (wr_en && wa == A_GAMMA_DATA) gamma_data_q <= (gamma_data_q & ~wmask) | (wr_data & wmask);
      end
      begin
        stat_thr_wr_o <= wr_en && wa == A_STAT_THR;
        if (wr_en && wa == A_STAT_THR) stat_thr_q <= (stat_thr_q & ~wmask) | (wr_data & wmask);
      end
      begin
        h_active_wr_o <= wr_en && wa == A_H_ACTIVE;
        if (wr_en && wa == A_H_ACTIVE) h_active_q <= (h_active_q & ~wmask) | (wr_data & wmask);
      end
      begin
        h_fp_wr_o <= wr_en && wa == A_H_FP;
        if (wr_en && wa == A_H_FP) h_fp_q <= (h_fp_q & ~wmask) | (wr_data & wmask);
      end
      begin
        h_sync_wr_o <= wr_en && wa == A_H_SYNC;
        if (wr_en && wa == A_H_SYNC) h_sync_q <= (h_sync_q & ~wmask) | (wr_data & wmask);
      end
      begin
        h_bp_wr_o <= wr_en && wa == A_H_BP;
        if (wr_en && wa == A_H_BP) h_bp_q <= (h_bp_q & ~wmask) | (wr_data & wmask);
      end
      begin
        v_active_wr_o <= wr_en && wa == A_V_ACTIVE;
        if (wr_en && wa == A_V_ACTIVE) v_active_q <= (v_active_q & ~wmask) | (wr_data & wmask);
      end
      begin
        v_fp_wr_o <= wr_en && wa == A_V_FP;
        if (wr_en && wa == A_V_FP) v_fp_q <= (v_fp_q & ~wmask) | (wr_data & wmask);
      end
      begin
        v_sync_wr_o <= wr_en && wa == A_V_SYNC;
        if (wr_en && wa == A_V_SYNC) v_sync_q <= (v_sync_q & ~wmask) | (wr_data & wmask);
      end
