      end
      begin
        sync_pol_wr_o <= wr_en && wa == A_SYNC_POL;
        if (wr_en && wa == A_SYNC_POL) sync_pol_q <= (sync_pol_q & ~wmask) | (wr_data & wmask);
      end
      begin
        lock_max_wr_o <= wr_en && wa == A_LOCK_MAX;
        if (wr_en && wa == A_LOCK_MAX) lock_max_q <= (lock_max_q & ~wmask) | (wr_data & wmask);
      end
      begin
        start_level_wr_o <= wr_en && wa == A_START_LEVEL;
        if (wr_en && wa == A_START_LEVEL) start_level_q <= (start_level_q & ~wmask) | (wr_data & wmask);
      end
      begin
        avi_wr_o <= wr_en && wa == A_AVI;
        if (wr_en && wa == A_AVI) avi_q <= (avi_q & ~wmask) | (wr_data & wmask);
      end
      begin
        out_ctrl_wr_o <= wr_en && wa == A_OUT_CTRL;
        if (wr_en && wa == A_OUT_CTRL) out_ctrl_q <= (out_ctrl_q & ~wmask) | (wr_data & wmask);
      end
      begin
        dsi_gaps_wr_o <= wr_en && wa == A_DSI_GAPS;
        if (wr_en && wa == A_DSI_GAPS) dsi_gaps_q <= (dsi_gaps_q & ~wmask) | (wr_data & wmask);
      end
      begin
        csitx_gap_wr_o <= wr_en && wa == A_CSITX_GAP;
        if (wr_en && wa == A_CSITX_GAP) csitx_gap_q <= (csitx_gap_q & ~wmask) | (wr_data & wmask);
      end
      begin
        dsi_cmd_wr_o <= wr_en && wa == A_DSI_CMD;
        if (wr_en && wa == A_DSI_CMD) dsi_cmd_q <= (dsi_cmd_q & ~wmask) | (wr_data & wmask);
      end
      begin
        dsi_cmd_byte_wr_o <= wr_en && wa == A_DSI_CMD_BYTE;
        if (wr_en && wa == A_DSI_CMD_BYTE) dsi_cmd_byte_q <= (dsi_cmd_byte_q & ~wmask) | (wr_data & wmask);
