  assign ctrl_o = ctrl_q[32-1:0];
  assign bypass_o = bypass_q[32-1:0];
  assign csi_o = csi_q[32-1:0];
  assign frame_size_o = frame_size_q[32-1:0];
  assign blc_r_o = blc_r_q[32-1:0];
  assign blc_gr_o = blc_gr_q[32-1:0];
  assign blc_gb_o = blc_gb_q[32-1:0];
  assign blc_b_o = blc_b_q[32-1:0];
  assign wb_r_o = wb_r_q[32-1:0];
  assign wb_g_o = wb_g_q[32-1:0];
